<?php session_start(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BUK EIMS Operations Console</title><link rel="icon" href="assets/buk-logo.png"><link rel="stylesheet" href="assets/buk-modern.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><script crossorigin src="https://unpkg.com/react@18/umd/react.development.js"></script><script crossorigin src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script><script src="https://cdn.jsdelivr.net/npm/axios/dist/axios.min.js"></script></head><body><div class="modern-shell"><aside class="modern-sidebar"><div class="brand-lockup"><img src="assets/buk-logo.png"><div><strong>BUK<span style="color:var(--buk-gold-light)"> EIMS</span></strong><small>BAYERO UNIVERSITY KANO</small></div></div><div class="modern-nav"><div class="nav-label">Operations</div><button class="active" onclick="setTab('triage')"><i class="fas fa-inbox"></i>Triage queue</button><button onclick="setTab('assignments')"><i class="fas fa-diagram-project"></i>Assignment board</button><button onclick="setTab('reports')"><i class="fas fa-chart-column"></i>Report builder</button><button onclick="setTab('sessions')"><i class="fas fa-calendar-days"></i>Academic sessions</button><button onclick="setTab('announcements')"><i class="fas fa-bullhorn"></i>Announcements</button><div class="nav-label">Navigation</div><button onclick="location.href='workspace.php'"><i class="fas fa-arrow-left"></i>Back to workspace</button></div></aside><main class="main-canvas"><header class="modern-topbar"><div><div class="crumb">BUK EIMS / OPERATIONS</div><div class="page-heading">Operations console</div></div><div class="top-actions"><button class="ghost-button" onclick="location.href='workspace.php'"><i class="fas fa-grid-2"></i>Workspace</button><button class="ghost-button" onclick="logout()"><i class="fas fa-arrow-right-from-bracket"></i>Sign out</button></div></header><div class="workspace-content"><div id="app"></div></div></main></div><script>
const API='./api.php';let csrf='';let user=null;let incidents=[];let cases=[];let lookups={};let tab='triage';
const api=async(action,data={})=>(await axios.post(`${API}?action=${action}`,data,{headers:{'X-Csrf-Token':csrf}})).data;
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const toast=m=>{const n=document.createElement('div');n.className='toast';n.innerHTML='<i class="fas fa-circle-check" style="color:var(--buk-gold-light);margin-right:8px"></i>'+esc(m);document.body.appendChild(n);setTimeout(()=>n.remove(),3000)};
async function init(){const a=await api('check_auth');if(!a.isAuthenticated){location.href='index.php';return}user=a.user;csrf=a.csrf_token;const [i,c,l]=await Promise.all([api('get_incidents'),api('get_cases'),api('get_lookups')]);incidents=i.data||[];cases=c.data||[];lookups=l.data||{};render()}
async function load(){const [i,c]=await Promise.all([api('get_incidents'),api('get_cases')]);incidents=i.data||[];cases=c.data||[];render()}
function setTab(t){tab=t;document.querySelectorAll('.modern-nav button').forEach(b=>b.classList.remove('active'));const buttons=[...document.querySelectorAll('.modern-nav button')];const index={triage:0,assignments:1,reports:2,sessions:3,announcements:4}[t];if(index!==undefined)buttons[index].classList.add('active');render()}
function head(eyebrow,title,sub,action=''){return `<div style="display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:17px"><div><div class="crumb" style="text-transform:uppercase;letter-spacing:.12em">${eyebrow}</div><h2 style="margin:5px 0 0;font-size:22px">${title}</h2><div style="font-size:12px;color:var(--muted);margin-top:6px">${sub}</div></div>${action}</div>`}
function render(){const app=document.getElementById('app');if(tab==='triage')app.innerHTML=triage();if(tab==='assignments')app.innerHTML=assignments();if(tab==='reports')app.innerHTML=reportBuilder();if(tab==='sessions')app.innerHTML=sessions();if(tab==='announcements')app.innerHTML=announcements()}
function triage(){const rows=incidents.filter(x=>x.status==='pending'||x.status==='reviewed');return head('Workflow control','Triage queue','Review incoming reports, return clarifications, and open formal cases.',`<button class="primary-button" onclick="load()"><i class="fas fa-rotate"></i>Refresh</button>`)+`<div class="stat-grid"><div class="stat-card"><div class="stat-top">New reports<div class="stat-icon"><i class="fas fa-inbox"></i></div></div><div class="stat-value">${incidents.filter(x=>x.status==='pending').length}</div><div class="stat-meta">Awaiting first review</div></div><div class="stat-card"><div class="stat-top">Reviewed<div class="stat-icon"><i class="fas fa-eye"></i></div></div><div class="stat-value">${incidents.filter(x=>x.status==='reviewed').length}</div><div class="stat-meta">Ready for case opening</div></div><div class="stat-card"><div class="stat-top">All reports<div class="stat-icon"><i class="fas fa-layer-group"></i></div></div><div class="stat-value">${incidents.length}</div><div class="stat-meta">Current registry</div></div><div class="stat-card"><div class="stat-top">Urgent focus<div class="stat-icon"><i class="fas fa-flag"></i></div></div><div class="stat-value">${rows.length}</div><div class="stat-meta">Requires attention</div></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Incoming incident reports</div><div class="panel-sub">Use the action menu on each record to progress the workflow.</div></div><span class="status-pill open">${rows.length} in queue</span></div><div style="overflow-x:auto"><table class="modern-table"><thead><tr><th>Reference</th><th>Student</th><th>Course</th><th>Offence</th><th>Reporter</th><th>Age</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.reference_no)}</strong><div class="row-meta">${esc(r.status)}</div></td><td>${esc(r.student_name)}<div class="row-meta">${esc(r.student_matric)}</div></td><td>${esc(r.course_code)}</td><td>${esc((r.offence_type||'').replace('_',' '))}</td><td>${esc(r.reporter_name)}</td><td>${Math.max(0,Math.floor((Date.now()-new Date(r.created_at))/86400000))}d</td><td><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="primary-button" onclick="review(${r.id},'reviewed')">Mark reviewed</button><button class="ghost-button" onclick="review(${r.id},'returned')">Return</button><button class="gold-button" onclick="openCase(${r.id})">Open case</button></div></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty-state"><i class="fas fa-check-double"></i><div>The triage queue is clear.</div></div>':''}</div></div>`}
async function review(id,decision){await api('review_incident',{incident_id:id,decision,note:decision==='returned'?'Please provide additional clarification before review.':''});toast('Triage decision saved');await load()}
async function openCase(incidentId){await api('open_case',{incident_id:incidentId});toast('Case opened successfully');await load()}
function assignments(){const members=lookups.committee_members||[];return head('Workflow control','Assignment board','Balance case ownership and panel assignments from one operational view.',`<button class="primary-button" onclick="load()"><i class="fas fa-rotate"></i>Refresh</button>`)+`<div class="panel"><div class="panel-head"><div><div class="panel-title">Active cases</div><div class="panel-sub">Assign committee members and track case ownership.</div></div></div><div style="overflow-x:auto"><table class="modern-table"><thead><tr><th>Case</th><th>Student</th><th>Stage</th><th>Priority</th><th>Committee member</th><th>Action</th></tr></thead><tbody>${cases.map(c=>`<tr><td><strong>${esc(c.case_no)}</strong><div class="row-meta">${esc(c.reference_no)}</div></td><td>${esc(c.student_name)}<div class="row-meta">${esc(c.student_matric)}</div></td><td><span class="status-pill ${c.stage}">${esc(c.stage.replace('_',' '))}</span></td><td><span class="status-pill ${c.priority}">${esc(c.priority)}</span></td><td><select id="committee-${c.id}" style="border:1px solid var(--line);border-radius:9px;padding:8px;font-size:11px"><option value="">Unassigned</option>${members.map(m=>`<option value="${m.id}" ${String(c.assigned_committee)===String(m.id)?'selected':''}>${esc(m.full_name)}</option>`).join('')}</select></td><td><button class="primary-button" onclick="assignCase(${c.id})">Save assignment</button></td></tr>`).join('')}</tbody></table>${!cases.length?'<div class="empty-state">No cases are available.</div>':''}</div></div>`}
async function assignCase(id){const member=document.getElementById('committee-'+id).value;await api('assign_committee',{case_id:id,committee_id:member});toast('Assignment updated');await load()}
function reportBuilder(){return head('Insights','Report builder','Choose a report type, review the current dataset, and export a CSV for institutional meetings.',`<button class="primary-button" onclick="downloadCsv()"><i class="fas fa-download"></i>Export CSV</button>`)+`<div class="grid-2"><div class="panel"><div class="panel-head"><div class="panel-title">Case outcomes</div></div><div class="panel-body">${['reported','under_review','investigation','hearing','resolved','dismissed'].map(s=>{const n=cases.filter(c=>c.stage===s).length;return `<div class="list-row"><div><div class="row-title">${s.replace('_',' ')}</div><div class="row-meta">Current cases</div></div><strong>${n}</strong></div>`}).join('')}</div></div><div class="panel"><div class="panel-head"><div class="panel-title">Incident mix</div></div><div class="panel-body">${[...new Set(incidents.map(i=>i.offence_type))].map(s=>{const n=incidents.filter(i=>i.offence_type===s).length;return `<div class="list-row"><div class="row-title">${(s||'other').replace('_',' ')}</div><strong>${n}</strong></div>`}).join('')||'<div class="empty-state">No incident data yet.</div>'}</div></div></div><div class="panel" style="margin-top:18px"><div class="panel-head"><div><div class="panel-title">Report preview</div><div class="panel-sub">The export includes reference, student, course, offence, stage, priority, and update date.</div></div></div><div style="overflow-x:auto"><table class="modern-table"><thead><tr><th>Case</th><th>Student</th><th>Course</th><th>Stage</th><th>Priority</th><th>Updated</th></tr></thead><tbody>${cases.slice(0,12).map(c=>`<tr><td>${esc(c.case_no)}</td><td>${esc(c.student_name)}</td><td>${esc(c.course_code||'')}</td><td>${esc(c.stage)}</td><td>${esc(c.priority)}</td><td>${new Date(c.updated_at).toLocaleDateString()}</td></tr>`).join('')}</tbody></table></div></div>`}
function downloadCsv(){const header='Case,Student,Course,Stage,Priority,Updated\n';const body=cases.map(c=>[c.case_no,c.student_name,c.course_code,c.stage,c.priority,c.updated_at].map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([header+body],{type:'text/csv'}));a.download='buk-eims-case-report.csv';a.click();toast('CSV report downloaded')}
function sessions(){return head('Administration','Academic sessions','Manage active semesters and examination periods for BUK EIMS.',`<button class="primary-button" onclick="saveSession()"><i class="fas fa-plus"></i>Save session</button>`)+`<div class="grid-2"><div class="panel"><div class="panel-head"><div class="panel-title">Session setup</div></div><div class="panel-body"><div class="form-grid"><div class="field"><label>Academic session</label><input id="session-name" value="2025/2026"></div><div class="field"><label>Semester</label><select id="session-sem"><option>First</option><option>Second</option></select></div><div class="field"><label>Start date</label><input id="session-start" type="date" value="2025-10-01"></div><div class="field"><label>End date</label><input id="session-end" type="date" value="2026-03-31"></div></div><label style="display:flex;gap:8px;align-items:center;margin-top:16px;font-size:12px;font-weight:700"><input id="session-active" type="checkbox" checked> Make this the active session</label><button class="primary-button" style="margin-top:16px" onclick="saveSession()">Save academic session</button></div></div><div class="panel"><div class="panel-head"><div class="panel-title">Configured sessions</div></div><div class="panel-body">${(lookups.sessions||[]).map(s=>`<div class="list-row"><div><div class="row-title">${esc(s.name)} · ${esc(s.semester)} Semester</div><div class="row-meta">${esc(s.start_date)} to ${esc(s.end_date)}</div></div>${s.is_active?'<span class="status-pill completed">Active</span>':'<span class="status-pill open">Planned</span>'}</div>`).join('')||'<div class="empty-state">No sessions configured.</div>'}</div></div></div>`}
async function saveSession(){await api('save_academic_session',{name:document.getElementById('session-name').value,semester:document.getElementById('session-sem').value,start_date:document.getElementById('session-start').value,end_date:document.getElementById('session-end').value,is_active:document.getElementById('session-active').checked});toast('Academic session saved');const l=await api('get_lookups');lookups=l.data;render()}
function announcements(){return head('Administration','Announcements','Publish clear updates for BUK EIMS users.',`<button class="primary-button" onclick="publishAnnouncement()"><i class="fas fa-paper-plane"></i>Publish</button>`)+`<div class="panel"><div class="panel-body"><div class="form-grid"><div class="field" style="grid-column:1/-1"><label>Announcement title</label><input id="ann-title" placeholder="e.g. First Semester hearing schedule"></div><div class="field" style="grid-column:1/-1"><label>Message</label><textarea id="ann-body" placeholder="Write a concise institutional update..."></textarea></div></div><button class="primary-button" style="margin-top:16px" onclick="publishAnnouncement()">Publish announcement</button></div></div>`}
async function publishAnnouncement(){await api('create_announcement',{title:document.getElementById('ann-title').value,body:document.getElementById('ann-body').value,audience_role:''});toast('Announcement published');document.getElementById('ann-title').value='';document.getElementById('ann-body').value=''}
async function logout(){await axios.post(`${API}?action=logout`);location.href='index.php'}
init().catch(e=>{document.getElementById('app').innerHTML='<div class="panel"><div class="panel-body">Unable to load operations console.</div></div>'});
</script></body></html>
